-- tools/arch-guard.lua: ARCHITECTURE.md is generated by the maintainer (tools/map.lua --write) after the last merge and is
-- never edited on a branch (AGENTS.md, "Generated files"): two branches that both regenerate it always conflict.
-- This fails when a branch's diff against the base touches it.
--
-- Usage: lua5.1 tools/arch-guard.lua [--base <ref>] [--root <repo or worktree>]
--   --base <ref>   what the branch is compared with (default origin/main): the diff runs from the merge base to the working
--                  tree, so committed, staged and unstaged changes all count
--   --root <dir>   the repository (default: the current folder)
-- Exit 0 and "arch-guard: PASS ..." when ARCHITECTURE.md is untouched, or when there is nothing to compare with (no such ref:
-- prints "SKIPPED"); exit 1 and "arch-guard: FAIL ..." when it is touched. The maintainer regenerating the file after the last
-- merge sets WUBER_ARCH_REGEN=1 (the check then passes and says so). A branch whose ONLY change to the file is exactly what
-- tools/map.lua --write produces also passes: the guard reruns "lua5.1 tools/map.lua --check" in --root, so a fresh
-- regeneration is accepted and any hand edit or stale copy still fails. Run by tools/quick-check.sh.
local base, root = "origin/main", "."
local i = 1
while i <= #arg do
	local a = arg[i]
	if a == "--base" then base = arg[i + 1] i = i + 1
	elseif a == "--root" then root = arg[i + 1] i = i + 1
	elseif a == "--help" or a == "-h" then
		print("usage: lua5.1 tools/arch-guard.lua [--base <ref>] [--root <dir>]  (fails when the branch changes ARCHITECTURE.md)")
		os.exit(0)
	else io.stderr:write("arch-guard: unknown argument " .. a .. "\n") os.exit(2) end
	i = i + 1
end

local windows = package.config:sub(1, 1) == "\\"
local function q(s) return '"' .. s .. '"' end
local function git(args)
	local cmd = "git -C " .. q(root) .. " " .. args .. (windows and " 2>nul" or " 2>/dev/null")
	local p = io.popen(cmd)
	if not p then return nil end
	local out = p:read("*a")
	local ok = p:close()
	return out, ok
end

local verified = git("rev-parse --verify -q " .. q(base .. "^{commit}"))
if not verified or not verified:find("%x%x%x%x") then
	print("arch-guard: SKIPPED (no " .. base .. " to compare with)")
	os.exit(0)
end
local mb = (git("merge-base " .. q(base) .. " HEAD") or ""):match("(%x+)")
if not mb then
	print("arch-guard: SKIPPED (no merge base between " .. base .. " and HEAD)")
	os.exit(0)
end
local touched = false
for _, cmd in ipairs({ "diff --name-only " .. mb, "ls-files --others --exclude-standard" }) do
	for line in (git(cmd) or ""):gmatch("[^\r\n]+") do
		if line == "ARCHITECTURE.md" then touched = true end
	end
end

if not touched then
	print("arch-guard: PASS (ARCHITECTURE.md is the same as in " .. base .. ")")
	os.exit(0)
end
if os.getenv("WUBER_ARCH_REGEN") == "1" then
	print("arch-guard: PASS (ARCHITECTURE.md changed; WUBER_ARCH_REGEN=1: the maintainer's regeneration after the last merge)")
	os.exit(0)
end
local mapScript = root .. "/tools/map.lua"
local mf = io.open(mapScript, "rb")
if mf then
	mf:close()
	local p = io.popen("lua5.1 " .. q(mapScript) .. " --check" .. (windows and " 2>nul" or " 2>/dev/null") .. " && echo MAPOK || echo MAPSTALE")
	local res = p and p:read("*a") or ""
	if p then p:close() end
	if res:find("MAPOK", 1, true) then
		print("arch-guard: PASS (ARCHITECTURE.md changed, and it is exactly what tools/map.lua --write produces)")
		os.exit(0)
	end
end
print("arch-guard: FAIL: this branch changes ARCHITECTURE.md.")
print("  The file is generated by the maintainer after the last merge (AGENTS.md, 'Generated files') and is never edited on a")
print("  branch: every pull request that regenerates it conflicts with every other one.")
print("  (Or regenerate it with: lua5.1 tools/map.lua --write, which the guard accepts.)")
print("  Put it back as it is in " .. base .. ":   git checkout " .. base .. " -- ARCHITECTURE.md")
print("  (and say in the pull request that the map needs regenerating, if a header, TOC or size changed).")
os.exit(1)
